const icons={play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 9h4M3 15h4M17 9h4M17 15h4"/>',court:'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="M3 12h18M8 3v4h8V3M8 21v-4h8v4"/><circle cx="12" cy="12" r="3"/>',spark:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z"/>',stack:'<path d="m3 7 9-4 9 4-9 4zM3 12l9 4 9-4M3 17l9 4 9-4"/>',data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',arrow:'<path d="M4 19 20 4M10 4h10v10"/>',zone:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="m4 12 8-8M4 18 18 4M10 20 20 10"/>',tag:'<path d="M3 3h9l9 9-9 9-9-9z"/><circle cx="8" cy="8" r="1"/>',send:'<path d="m3 3 19 9-19 9 4-9zM7 12h15"/>',shield:'<path d="m12 3 8 3v6c0 4-8 9-8 9s-8-5-8-9V6zM8 12l3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=(key)=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[key]||icons.spark}</svg>`;
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const store=new ArenaStore();
const state={project:null,projects:[],playId:null,time:0,route:'watch',audience:'fan',layers:{paths:true,labels:true,zones:true,defenders:false,ball:true,metrics:false},focus:null,analyses:{},narrations:{},answer:null,decision:null,compareId:null,url:null,raf:null,pending:null,editing:null,annotationStart:null,exporting:false,voiceAvailable:false,localServer:false,voiceSelected:false,lastFilm:null,provider:'local',cloudCapabilities:null,original:false};
let toastTimer;
const decodedTimes=new WeakMap();let frameObservers=[];
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,6500);}
function showDialog(title,body,actions=''){ $('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${h(title)}</h2><button data-action="close" aria-label="关闭对话框">×</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();}
const format=(v,d=1)=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(d):'—';
const sec=v=>format(v,2)+' s';
const sourceBadge=kind=>kind==='official'?'来源声明 · 官方':/schematic|synthetic/.test(kind||'')?'合成 / 示意':kind==='measured'?'导入测量':'用户提供';
const play=()=>state.project?.plays.find(p=>p.id===state.playId)||state.project?.plays[0];
const currentAnalysis=()=>state.analyses[play()?.id];
function presentedTime(p=play()){const v=p&&$(`video[data-video="${CSS.escape(p.id)}"]`);return v?displayTime(v,decodedTimes.get(v)):state.time;}
function refreshAnalysis(){
  state.analyses={};state.narrations={};
  for(const p of state.project?.plays||[]){const a=analyzePossession(p);state.analyses[p.id]=a;const n=buildNarration(p,a,{audience:state.audience,language:'zh'});n.cues=n.cues.map(c=>{const edited=state.project.narrationEdits?.[`${state.audience}:${p.id}:${c.start}`]??state.project.narrationEdits?.[`${p.id}:${c.start}`];return {...c,originalText:c.text,text:edited??c.text,origin:edited==null?'evidence-engine':'manual'};});state.narrations[p.id]=n;}
}
function reviewSignature(){return JSON.stringify({audience:state.audience,layers:state.layers});}
async function save(message){cancelPreview();try{validateProject(state.project);state.project=await store.save(state.project,state.project.revision);state.dirty=false;state.projects=await store.list();refreshAnalysis();$('#storage-status').textContent=`已保存 · 修订 ${state.project.revision} · 浏览器本机`;
  if(message)toast(message);return state.project;
}catch(error){state.dirty=true;$('#storage-status').textContent='未保存草稿 · 请下载备份后重新载入';throw error;}
}
async function activate(project){
  cancelPreview();stopPlayback();if(state.url?.startsWith('blob:'))URL.revokeObjectURL(state.url);
  if(state.lastFilm?.url?.startsWith('blob:'))URL.revokeObjectURL(state.lastFilm.url);state.lastFilm=null;state.lastExport=null;state.preview=null;
  state.project=project;state.dirty=false;state.playId=project.plays[0]?.id??null;state.time=project.plays[0]?.start??0;if(project.provenance.kind==='synthetic'&&project.plays[0])state.time=Math.max(project.plays[0].start,(project.plays[0].shotTime??project.plays[0].start)-.7);state.answer=null;state.decision=null;state.focus=null;
  state.audience=project.renderSettings?.audience||'fan';state.layers={paths:true,labels:true,zones:true,defenders:false,ball:true,metrics:false,...project.renderSettings?.layers};
  state.url=null;if(project.video?.id){const blob=await store.media(project.video.id);if(blob)state.url=URL.createObjectURL(blob);}else if(project.video?.url==='media/demo.mp4')state.url='media/demo.mp4';
  refreshAnalysis();render();
}
async function playVideo(video){try{await video.play();}catch(error){if(error.name==='AbortError')return;throw new Error(error.name==='NotSupportedError'?'视频格式不能播放，请绑定兼容的视频。':'视频暂时无法播放，请检查素材后重试。');}}
function stopPlayback(){cancelAnimationFrame(state.raf);$$('video').forEach(v=>v.pause());}
function cancelPreview(){state.preview?.frameController?.abort();state.preview=null;}
function navigate(route){if(state.exporting){toast('正在录制成片，请先完成或取消。');return;}location.hash=`/${route}`;}
function intro(title,eyebrow,description,actions=''){return `<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="intro-actions">${actions}</div></div>`;}
function sources(){return `<div class="source-strip"><span class="pill ${state.project.provenance.kind==='synthetic'?'demo':'blue'}"><i class="dot"></i>${h(state.project.provenance.label||sourceBadge(state.project.provenance.kind))}</span><span>${state.project.plays.length} 个回合 · 时间以视频秒数为准</span><span class="grow"></span><button class="text-link" data-action="evidence">查看数据与判断依据</button></div>`;}
function stage(p,{compare=false}={}){
  const aspect=state.project.video?.width&&state.project.video?.height?state.project.video.width/state.project.video.height:16/9;
  return `<div class="panel film-panel"><div class="film-top"><span class="pill blue">${compare?'对照回合':'原画面 + 战术图层'}</span><span>${h(p?.clock||'视频时间')}</span><strong>${h(p?.team||'')} · ${h(p?.player||'待标记球员')}</strong></div><div class="stage ${state.editing&&!compare?'editable':''}" style="aspect-ratio:${aspect}" data-play="${h(p?.id)}">${state.url?`<video data-video="${h(p?.id)}" src="${h(state.url)}" playsinline preload="auto" muted></video><canvas class="overlay" data-overlay="${h(p?.id)}" width="1280" height="${Math.round(1280/aspect)}" aria-label="比赛画面上的战术标注"></canvas><div class="stage-title"><span>READ THE POSSESSION</span><strong>${h(p?.title)}</strong></div><span class="video-badge">${h(sourceBadge(state.project.provenance.kind))}</span><div class="stage-cue"><span data-cue="${h(p?.id)}"></span></div>`:`<div class="empty-media">${icon('film')}<h3>把数据带回原始比赛画面</h3><p>请绑定这一场比赛的视频。数据已保存，视频叠加会在时间和镜头校准后运行。</p><button class="button primary" data-action="video">绑定本地视频</button></div>`}</div>${!compare?`<div class="player-controls"><button class="play-toggle" data-action="play" aria-label="播放或暂停">${icon('play')}</button><span class="timecode" id="current-time">${timestamp(state.time).slice(3,11)}</span><input data-seek type="range" aria-label="回合播放时间" min="${p?.start||0}" max="${p?.end||1}" step="0.01" value="${state.time}"><span class="timecode">${timestamp(p?.end||0).slice(3,11)}</span><select data-rate aria-label="播放速度"><option value="0.5">0.5×</option><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option></select><button class="icon-button" data-action="frame-back" aria-label="后退约 33 毫秒">‹</button><button class="icon-button" data-action="frame-next" aria-label="前进约 33 毫秒">›</button></div>${layersBar()}`:''}</div>`;
}
function layersBar(){return `<div class="layer-bar">${[['paths','arrow','移动路径'],['labels','tag','球员标记'],['zones','zone','出手区域'],['defenders','shield','防守距离']].map(([key,ic,label])=>`<button class="layer-toggle ${state.layers[key]?'active':''}" data-action="layer" data-layer="${key}" aria-pressed="${!!state.layers[key]}">${icon(ic)}${label}</button>`).join('')}<span class="key-tag">SPACE 播放 · ← → 微调 33ms</span></div>`;}
function metrics(a){return `<div class="metric-band">${['difficulty','gravity','leverage'].map(key=>{const m=a?.metrics?.[key];const value=m?.available?h(primaryMetricText(m)):'—';const label=m?.label||{difficulty:'投篮难度 / xFG',gravity:'球员引力',leverage:'关键度'}[key];return `<div class="metric-box"><div class="metric-label">${h(label)} <button class="text-link" data-action="metric" data-key="${key}" aria-label="查看${h(label)}口径">ⓘ</button></div><div class="metric-number">${value}</div><p class="metric-definition">${key==='difficulty'?'读取输入预测，保留原始定义':key==='gravity'?'来源读数 · 几何距离不替代引力模型':m?.semantics==='possession_win_probability_opportunity'?'演练口径 · 非球员累计 Leverage':'按照数据提供者定义解释'}</p>${m?.normalized!=null?`<div class="metric-track" aria-hidden="true"><span style="width:${Math.max(0,Math.min(100,m.normalized*100))}%"></span></div>`:''}</div>`;}).join('')}</div>`;}
function playList(){const ranked=rankPossessions(state.project.plays);return `<div class="panel"><div class="panel-head"><h2>值得回看的时刻</h2><span class="pill">${ranked.length}</span></div><div class="play-list">${ranked.map((r,i)=>{const p=state.project.plays.find(p=>p.id===r.playId);return `<button class="play-item ${p.id===play()?.id?'active':''}" data-action="select-play" data-id="${h(p.id)}"><div class="play-item-top"><span class="play-index">${String(i+1).padStart(2,'0')}</span><span>${h(p.clock||timestamp(p.start).slice(3,11))}</span></div><h3>${h(p.title)}</h3><p>${h(p.team)} · ${h(p.player)} · ${format(p.end-p.start,1)} 秒</p><div class="microbars" aria-hidden="true">${r.analysis.rank.components.map(c=>`<span style="width:${c.weight}%;opacity:${c.normalized==null?.2:.4+c.normalized*.6}"></span>`).join('')}</div></button>`;}).join('')}</div></div>`;}
function traceLabel(value){return ({validate_normalized_plays:'核对比赛数据',resolve_query_scope:'定位相关回合',query_opportunities:'检索空间变化',read_metrics:'读取指标',search_plays:'查找回合',read_evidence:'核对证据',publish_story:'编排解说',query_metrics:'检查指标口径',rank_possessions:'计算回看顺序'})[value]||'核对数据依据';}
function agentPanel(){const p=play(),a=currentAnalysis(),n=state.narrations[p?.id];const claims=n?.claims?.filter(c=>c.type!=='outcome').slice(0,3)||[];
  return `<div class="panel"><div class="panel-head"><div class="agent-brand"><span class="agent-symbol">${icon('spark')}</span><div><h2>比赛解读员</h2><span class="agent-status">${state.provider==='local'?'本地证据引擎 · 大模型未连接':h(state.provider)+' 模型模式'}</span></div></div><button class="text-link" data-action="agent-settings">连接</button></div><div class="agent-lead"><span class="eyebrow">THE STORY BEHIND THE SHOT</span><h3>${h(p?.title)}</h3><p>${h(state.audience==='fan'?'先看选择，再看结果。点击一条解释，回到它发生的画面。':'逐项读取指标、采样与时序，区分输入事实、几何描述与因果推断。')}</p></div><div class="claim-list">${claims.map((c,i)=>`<button class="claim" data-action="claim" data-id="${h(c.id)}"><span class="claim-index">${String(i+1).padStart(2,'0')}</span><div><p>${h(c.text)}</p><small>${timestamp(c.t).slice(3,11)} · ${c.evidenceIds?.length||0} 条证据 ↗</small></div></button>`).join('')}${a?.tactical.shotContext?`<button class="claim" data-action="seek" data-time="${a.tactical.shotContext.t}"><span class="claim-index">↗</span><div><p>出手采样：${h(a.tactical.shotContext.nearestDefender?.name||'防守者未知')} 距离 ${format(a.tactical.shotContext.nearestDefender?.distanceFt,1)} ft</p><small>${h(sourceBadge(a.tactical.shotContext.kind))} · 采样偏移 ${format(a.tactical.shotContext.timeOffsetSec,2)} s</small></div></button>`:''}</div><div class="agent-query"><div class="suggestions">${['为什么值得回看？','引力说明了什么？','哪里出现空档？'].map(q=>`<button class="suggestion" data-action="ask" data-question="${h(q)}">${h(q)}</button>`).join('')}</div><form class="query-form" id="query-form"><input name="question" aria-label="向比赛解读员提问" placeholder="问一个关于这场比赛的问题…" maxlength="1200" required><button aria-label="发送问题">${icon('send')}</button></form></div>${state.answer?`<div class="answer"><span class="eyebrow">${h(state.answer.question)}</span><p>${h(state.answer.answer).replace(/\n/g,'<br>')}</p><div class="tool-trace">${(state.answer.trace||[]).map(t=>`<span class="tool-step">✓ ${h(traceLabel(t.tool||t.step||t.name))}</span>`).join('')}</div><div class="inline-actions" style="margin-top:10px"><button class="text-link" data-action="answer-evidence">核对引用的证据</button>${(state.answer.matches||[]).slice(0,3).map(m=>`<button class="text-link" data-action="select-play" data-id="${h(m.playId)}">${h(m.playId)} ↗</button>`).join('')}</div></div>`:''}</div>`;
}
function miniCourt(){const p=play();const players=p?.tracks?.[0]?.players||[];return `<div class="panel"><div class="panel-head"><h2>同一时刻 · 球场视角</h2><span class="pill">${h(sourceBadge(p?.tracking?.kind))}</span></div><canvas id="mini-court" class="mini-court" width="640" height="480" role="img" aria-label="与比赛视频同步的球场位置图"></canvas><div class="player-select">${players.filter(r=>r.team===p.team).map(r=>`<button class="player-chip ${state.focus===r.id?'active':''}" data-action="focus" data-id="${h(r.id)}">${h(r.name||r.id)}</button>`).join('')}</div><div class="court-caption"><span>进攻 ${h(p?.team)} · 点选球员追踪</span><span id="court-time">${sec(state.time)}</span></div></div>`;}
function watch(){const p=play(),a=currentAnalysis();if(!p)return emptyWorkspace();const beats=storyBeats(p,state.narrations[p.id],a);return intro(h(coreQuestion(p,a)),'COURTLENS / 看懂这一球','先看原回合，再用画面与数据解释一个关键选择。',`<div class="segmented"><button data-action="audience" data-value="fan" class="${state.audience==='fan'?'active':''}">轻松看懂</button><button data-action="audience" data-value="analyst" class="${state.audience==='analyst'?'active':''}">专业解读</button></div><button class="button ghost compact" data-action="decision">${icon('clock')} 结果揭晓前</button>`)+sources()+`<div class="spectator-layout"><section class="spectator-film">${stage(p)}<div class="view-switch"><div class="segmented"><button data-action="view-mode" data-value="enhanced" class="${!state.original?'active':''}" aria-pressed="${!state.original}">增强回放</button><button data-action="view-mode" data-value="original" class="${state.original?'active':''}" aria-pressed="${state.original}">原片对照</button></div><span>共用原片与同一播放时刻</span><button class="text-link" data-action="add-clip">加入制作片单 ↗</button></div><div class="moment-metric" id="moment-metric" aria-live="polite"></div><div class="beat-track">${beats.map((b,i)=>`<button data-action="story-beat" data-index="${i}" data-time="${b.start}" class="story-beat"><span>0${i+1} / ${h(b.label)}</span><strong>${timestamp(b.start).slice(3,12)}</strong><small>${b.evidenceIds.length} 条证据 · 点击回看</small></button>`).join('')||'<p class="form-note">当前没有足够的可引用讲解点，请在制作端核对输入。</p>'}</div></section><aside class="spectator-story"><div class="panel"><div class="panel-head"><h2>看见选择</h2><span class="pill">${h(p.team||'回合')}</span></div><div class="panel-body"><p class="story-now" id="story-now">播放到讲解时刻，展开有依据的解释。</p><button class="button compact" data-action="current-beat-evidence">查看这一刻的依据</button><p class="form-note">${h(p.title)} · ${format(p.end-p.start,1)} 秒<br>${h(p.player||'球员身份未提供')}</p></div></div>${playList()}<div class="panel rail-note"><strong>制作与复核</strong><p>修订解说、检查移动镜头、导出同步字幕和成片。</p><a class="button compact" href="#/director">进入故事导演</a><button class="text-link" data-action="readiness">本地验收清单</button></div></aside></div><details class="professional-details" ${state.audience==='analyst'?'open':''}><summary>展开专业读数与空间证据</summary><div class="watch-grid"><section class="content-column">${metrics(a)}${scopedMetricTable(a)}</section><aside class="right-rail">${agentPanel()}${miniCourt()}</aside></div></details>`;}
function scopedMetricTable(a){const records=[...new Map([...(a?.scopedMetrics||[]),...(a?.metricContext||[])].map(m=>[m.evidenceId,m])).values()];return records.length?`<div class="panel"><div class="panel-head"><h2>数据口径与统计范围</h2><span class="pill">Adapter v2</span></div><div class="data-table-wrap"><table class="data-table"><tr><th>读数</th><th>可用时间</th><th>出处</th></tr>${records.map(m=>`<tr><td>${h(formatScopedMetric(m))}</td><td>${m.availableAt==null?'未提供':sec(m.availableAt)}</td><td>${h(m.dictionaryVersion||m.version||'')} · ${h(m.provenance?.source||m.source||'输入')}</td></tr>`).join('')}</table></div></div>`:'';}

function emptyWorkspace(){return `<div class="empty-state"><span class="eyebrow">START WITH THE GAME</span><h2>把一场比赛，变成可以读懂的故事</h2><p>接入比赛视频、回合数据与镜头标定，开始观赛、对照和内容制作。</p><button class="button primary" data-action="import">接入比赛素材</button><button class="button ghost" data-action="rehearsal">载入合成演练</button></div>`;}
function distanceChart(p,a,other,b){
  const series=[{p,a,color:'line'},{p:other,a:b,color:'line second'}].filter(x=>x.p);const all=series.flatMap(x=>x.a?.temporal?.samples?.filter(s=>s.shooterDefenderDistanceFt!=null)||[]);if(!all.length)return '<div class="empty-chart">没有可验证的球场坐标，无法生成防守距离曲线。</div>';
  const maxX=Math.max(...series.map(x=>x.p.end-x.p.start)),maxY=Math.max(8,...all.map(s=>s.shooterDefenderDistanceFt));const W=680,H=210,x=t=>45+t/maxX*(W-65),y=v=>H-28-v/maxY*(H-50);
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="不同回合随时间的最近防守者距离"><title>出手球员到已记录最近防守者距离，单位英尺；横轴为回合相对秒数</title>${[0,1,2,3,4].map(i=>{const v=maxY*i/4;return `<path class="grid" d="M45 ${y(v)}H${W-15}"/><text x="35" y="${y(v)+4}" text-anchor="end">${format(v,1)}</text>`;}).join('')}<path class="threshold" d="M45 ${y(6)}H${W-15}"/><text x="${W-17}" y="${y(6)-5}" text-anchor="end">空间窗阈值 6 ft</text>${series.map(({p,a,color})=>{let path='',last=null;for(const s of a.temporal.samples){if(s.shooterDefenderDistanceFt==null){last=null;continue;}const contiguous=last!=null&&s.t-last<=p.tracking.maxGap;path+=`${contiguous?'L':'M'}${x(s.t-p.start).toFixed(2)},${y(s.shooterDefenderDistanceFt).toFixed(2)} `;last=s.t;}return `<path class="${color}" d="${path}"/>`;}).join('')}${[0,.25,.5,.75,1].map(f=>`<text x="${x(maxX*f)}" y="${H-7}" text-anchor="middle">${format(maxX*f,1)} s</text>`).join('')}<path class="cursor" id="chart-cursor" d="M${x(state.time-p.start)} 15V${H-28}"/></svg>`;
}
function opportunityWindows(p,a){const grouped=new Map();for(const w of a.temporal.opportunityWindows||[]){if(!grouped.has(w.playerId))grouped.set(w.playerId,[]);grouped.get(w.playerId).push(w);}return grouped.size?[...grouped].map(([id,windows])=>`<div class="window-row"><span class="label">${h(id)}</span><div class="window-track">${windows.map(w=>`<span title="${h(id)} ${format(w.start-p.start,2)}–${format(w.end-p.start,2)}秒；最小距离${format(w.minDistanceFt,1)}ft" style="left:${100*(w.start-p.start)/(p.end-p.start)}%;width:${100*(w.end-w.start)/(p.end-p.start)}%"></span>`).join('')}${Number.isFinite(p.shotTime)?`<i style="left:${100*(p.shotTime-p.start)/(p.end-p.start)}%"></i>`:''}</div><span>${format(windows.reduce((s,w)=>s+w.duration,0),1)} s</span></div>`).join(''):'<div class="empty-chart">当前采样未确认持续空间窗。<br>这不等于场上没有空档。</div>';}
function lab(){const p=play();if(!p)return emptyWorkspace();const other=state.project.plays.find(q=>q.id===state.compareId&&q.id!==p.id)||state.project.plays.find(q=>q.id!==p.id),a=currentAnalysis(),b=other&&state.analyses[other.id],incompatible=new Set(other?rankPossessions([p,other])[0].rank.incompatibleFields:[]);
  // Raw input readings still need the same basis even when neither has a ranking signature.
  const sourceClass=m=>['synthetic','schematic'].includes(m.kind)?'schematic':'source-record';
  const knownBasis=m=>m.key==='gravity'?m.semantics==='supplied_metric'&&m.definition.trim().length>0&&m.unit.trim().length>0&&m.unit!=='输入单位':m.signature!==null;
  const comparable=(k,m,n)=>m.available&&n?.available&&knownBasis(m)&&knownBasis(n)&&n.semantics===m.semantics&&n.unit===m.unit&&n.definition===m.definition&&n.higherIs===m.higherIs&&sourceClass(n)===sourceClass(m)&&JSON.stringify(n.range)===JSON.stringify(m.range)&&!incompatible.has(k);
  return intro('把选择，放在一起看','TACTICAL LAB / 比赛实验室','同步对照回合、检查机会窗口，在结果出现之前理解出手选择。',`<button class="button compact" data-action="decision">${icon('clock')} 决策冻结</button>`)+sources()+`<div class="decision-panel"><div><span class="eyebrow">BEFORE THE OUTCOME</span><h2>如果球还没离手，你会怎样选择？</h2><p>在出手前冻结画面，隐藏结果与未来数据。记录选择后再回看。</p></div><div class="decision-actions"><button class="button primary" data-action="decision">进入决策体验</button></div></div><div class="lab-grid"><section>${stage(p,{compare:true})}</section><section>${other?stage(other,{compare:true}):'<div class="panel empty-chart">至少导入两个回合，才能对照。</div>'}</section></div><div class="lab-control"><button class="button compact" data-action="compare-play">${icon('play')} 同步播放</button><strong>相对回合时间</strong><input type="range" data-compare-seek aria-label="两个回合的相对播放位置" min="0" max="1" step=".001" value="${(state.time-p.start)/(p.end-p.start)}"><select class="button compact" data-compare-select aria-label="选择对照回合">${state.project.plays.filter(q=>q.id!==p.id).map(q=>`<option value="${h(q.id)}" ${other?.id===q.id?'selected':''}>${h(q.title)}</option>`).join('')}</select></div><div class="section-grid"><div class="panel"><div class="panel-head"><h2>防守距离，怎样随时间变化？</h2><div class="legend"><span><i></i>${h(p.id)}</span><span><i class="red"></i>${h(other?.id||'')}</span></div></div><div class="panel-body">${distanceChart(p,a,other,b)}<p class="chart-note">这是输入球场坐标的几何距离，不能等价为 NBA Gravity 或防守压力。采样缺口断线，不跨缺口补画。${h(sourceBadge(p.tracking.kind))}。</p></div></div><div class="panel"><div class="panel-head"><h2>机会窗口</h2><span class="pill">采样阈值描述</span></div><div class="panel-body">${opportunityWindows(p,a)}<p class="chart-note">最近已记录防守者距离 ≥6 ft、连续采样且防守名单完整时才确认窗口。阈值是本产品的编辑规则；不是官方空位或球员引力定义。</p></div></div><div class="panel"><div class="panel-head"><h2>同一出手，哪些读数可以比较？</h2></div><div class="panel-body"><table class="stat-table"><tr><th>证据</th><th>${h(p.id)}</th><th>${h(other?.id||'对照')}</th></tr>${['difficulty','gravity','leverage'].map(k=>{const m=a.metrics[k],n=b?.metrics[k];return `<tr><td>${h(m.label)}</td><td class="num">${m.available?format(m.value,3):'未提供'}</td><td class="num">${comparable(k,m,n)?format(n.value,3):'不可直接比较'}</td></tr>`;}).join('')}<tr><td>结果</td><td>${h(p.outcome)}</td><td>${h(other?.outcome||'unknown')}</td></tr></table><p class="chart-note">结果与选择分开阅读；同名指标的定义或单位不同，会保留原读数并拒绝统一尺度。</p></div></div><div class="panel"><div class="panel-head"><h2>可见的传球线</h2><button class="text-link" data-action="evidence">依据 ↗</button></div><div class="panel-body"><table class="stat-table"><tr><th>接球点</th><th>线路最小防守间距</th><th>接球点防守距离</th></tr>${a.tactical.alternatives.slice(0,4).map(t=>`<tr><td>${h(t.playerName)}</td><td>${format(t.laneClearanceFt,1)} ft</td><td>${format(t.receivingDefenderDistanceFt,1)} ft</td></tr>`).join('')}</table><p class="chart-note">几何线路不预测传球成功率、篮下收益或换一种选择能否得分。这里提供观察依据，由观众与分析员核对。</p></div></div></div>`;
}
function director(){const p=play();if(!p)return emptyWorkspace();let plan;try{plan=playlistPlan(state.project,state.narrations);}catch(error){plan={clips:[],cues:[],duration:0,error:error.message};}
  return intro('把一次攻防，讲成一个故事','DIRECTOR / 篮球故事制作','选回合、剪入出点、核对字幕和图层，导出真正可以播放的成片。',`<button class="button compact" data-action="add-clip">＋ 当前回合加入片单</button>`)+sources()+`<div class="director-grid"><section class="content-column">${stage(p)}<div class="panel"><div class="panel-head"><h2>逐句解说与画面锚点</h2><span class="pill">${h(state.audience==='fan'?'轻松看懂':'专业解读')}</span></div>${(state.narrations[p.id]?.cues||[]).map((c,i)=>`<div class="narration-row"><button class="text-link cue-time" data-action="seek" data-time="${c.start}">${timestamp(c.start).slice(3,12)} → ${timestamp(c.end).slice(3,12)}</button><p>${h(c.text)}</p><textarea aria-label="编辑第 ${i+1} 段解说" data-cue-edit="${h(p.id)}:${c.start}" maxlength="240">${h(c.text)}</textarea><small>${c.evidenceIds.length} 条证据 · 修改后需重新复核</small></div>`).join('')}<div class="panel-body"><button class="button compact" data-action="save-cues">保存解说修改</button><button class="text-link" data-action="speech" style="margin-left:15px">试听当前解说</button></div></div><div class="panel"><div class="panel-head"><h2>画面标注工具</h2><button class="text-link" data-action="clear-annotations">清除本回合人工标注</button></div><div class="panel-body"><div class="inline-actions"><button class="button compact ${state.editing==='arrow'?'primary':''}" data-action="annotate" data-kind="arrow">${icon('arrow')} 画箭头</button><button class="button compact ${state.editing==='zone'?'primary':''}" data-action="annotate" data-kind="zone">${icon('zone')} 画区域</button><button class="button compact" data-action="annotate" data-kind="tag">${icon('tag')} 文字标签</button><button class="button compact ghost" data-action="annotate" data-kind="">结束标注</button></div><p class="form-note">在暂停画面上依次点击起点与终点。标注显示在当前时刻之后 3 秒内；来源记录为人工，不冒充自动识别。</p></div></div></section><aside class="content-column"><div class="panel"><div class="panel-head"><h2>故事片单</h2><span class="pill">${format(plan.duration,1)} s</span></div>${plan.error?`<div class="error-box">${h(plan.error)}</div>`:''}${(state.project.playlist||[]).map((c,i)=>{const q=state.project.plays.find(p=>p.id===c.playId);return `<div class="clip"><span class="clip-num">${String(i+1).padStart(2,'0')}</span><div class="clip-info"><strong>${h(q?.title)}</strong><button class="text-link" data-action="select-play" data-id="${h(c.playId)}">${h(c.playId)} · 预览 ↗</button></div><div class="clip-controls"><input type="number" data-clip-start="${i}" aria-label="片段 ${i+1} 开始秒数" step=".01" value="${c.start??q.start}" min="${q.start}" max="${q.end}"><input type="number" data-clip-end="${i}" aria-label="片段 ${i+1} 结束秒数" step=".01" value="${c.end??q.end}" min="${q.start}" max="${q.end}"><button data-action="clip-up" data-index="${i}" aria-label="片段上移" ${i===0?'disabled':''}>↑</button><button data-action="clip-down" data-index="${i}" aria-label="片段下移" ${i===state.project.playlist.length-1?'disabled':''}>↓</button><button data-action="clip-remove" data-index="${i}" aria-label="移除片段">×</button></div></div>`;}).join('')||'<div class="playlist-empty">从观赛台挑选回合，开始编排。</div>'}<div class="panel-body"><button class="button compact" data-action="save-clips">保存片段入出点</button><button class="button compact" style="margin-left:8px" data-action="preview-film">连续预览片单</button><button class="text-link" style="margin-left:8px" data-action="stop-preview">停止预览</button><p id="preview-status" class="form-note">按已保存的裁剪点连续播放。预览使用解码帧时钟；精确片长以导出后核对为准。</p><p class="form-note">片段按这里的顺序拼接。字幕重新映射到成片时间，不沿用原比赛绝对秒数。</p></div></div><div class="panel"><div class="panel-head"><h2>发布前复核</h2><span class="pill ${p.reviewed?'ok':''}">${p.reviewed?'当前回合已核对':'待核对'}</span></div><div class="panel-body"><label class="review-check"><input type="checkbox" data-reviewed ${p.reviewed?'checked':''}>我已核对当前回合的时间、标注、解说与来源。</label><div class="review-status">${state.project.playlist.length?`${state.project.playlist.filter(c=>state.project.plays.find(p=>p.id===c.playId)?.reviewed).length} / ${state.project.playlist.length} 个片段对应回合已核对。`:'先加入片段，再导出成片。'}<br>WebM 在浏览器实际录制，最长 180 秒。本机入口会将生成的成片保存在本机工作目录；网页版保留在当前页面。可选择本机中文配音 MP4，原片声音不写入成片。</div><label class="review-check"><input id="include-voice" type="checkbox" ${state.voiceSelected?'checked':''} ${state.voiceAvailable?'':'disabled'}>同步中文配音 · ${state.voiceAvailable?'本机合成，导出 MP4':'需本机 macOS 语音服务'}</label><div class="export-grid"><button class="button primary" data-action="export-video" ${!plan.clips.length||!state.url?'disabled':''}>${icon('film')} 导出战术成片</button><button class="button" data-action="export-vtt" ${!plan.clips.length?'disabled':''}>同步字幕 VTT</button><button class="button" data-action="export-story">证据故事报告</button><button class="button" data-action="export-plan">分镜与证据 JSON</button><button class="button" data-action="export-story-plan" ${!plan.clips.length?'disabled':''}>已审 StoryPlan</button></div>${state.lastFilm?`<div class="callout" style="margin-top:16px"><b>${state.lastFilm.sourceRevision===state.project.revision?'已生成成片':'历史成片 · 当前内容已修改，请重新导出'} · 修订 ${state.lastFilm.sourceRevision}</b><p>${format(state.lastFilm.bytes/1048576,1)} MiB · ${state.lastFilm.frameCount} 帧 · ${state.lastFilm.audio?'中文配音':'无音轨'}</p><a id="last-film" class="button primary compact" href="${h(state.lastFilm.url)}" download="${h(state.lastFilm.filename)}">下载已生成成片</a><button class="text-link" data-action="export-audit">录制校验记录</button></div>`:''}<div id="export-progress" hidden><div class="progress"><span></span></div><p class="form-note" id="export-message"></p><button class="text-link" data-action="cancel-export">取消录制</button></div></div></div><div class="panel"><div class="panel-head"><h2>交付物</h2></div><div class="panel-body"><ul class="boundary-list"><li><strong>播放作品</strong>原画面、实时图层与同步字幕</li><li><strong>核对记录</strong>逐句引用、字段口径、画面时间</li><li><strong>可继续编辑</strong>项目 JSON 和原始视频分别保留</li></ul><div class="inline-actions" style="margin-top:13px"><button class="text-link" data-action="backup">下载项目备份</button><button class="text-link" data-action="history">修订历史</button></div></div></div></aside></div>`;
}
function pipeline(){const s=summarize(state.project),p=play();return intro('让每一层分析，都有来处','DATA PIPELINE / 素材与校准','从官方字段到比赛秒数，再到镜头坐标。未知的数据，留在未知状态。',`<button class="button compact primary" data-action="import">导入回合数据</button>`)+sources()+`<div class="pipeline-grid"><section class="content-column"><div class="panel"><div class="panel-head"><h2>接入流程</h2><span class="pill">${state.project.video?'视频已登记':'等待素材'}</span></div><div class="pipeline-step"><span class="step-num">01</span><div><h3>绑定比赛视频</h3><p>${state.project.video?`${h(state.project.video.name||'合成演练视频')} · ${sec(state.project.video.duration)} · ${state.project.video.width||'—'} × ${state.project.video.height||'—'}`:'导入自己的比赛片段或赛方授权素材，视频 Blob 保存在当前浏览器。'}</p><button class="button compact" data-action="video">${state.project.video?'更换视频':'导入本地视频'}</button></div></div><div class="pipeline-step"><span class="step-num">02</span><div><h3>回合与深度指标</h3><p>${s.plays} 个回合，${s.metrics} 个有指标，${s.tracking} 个有球场轨迹，${s.unknown} 个结果未知。支持带字段映射的 CSV、逐回合 JSON、指标 Adapter v2 与 Arena 项目备份。</p><div class="inline-actions"><button class="button compact" data-action="import">导入数据</button><button class="button compact ghost" data-action="new-play">人工新增回合</button><button class="button compact ghost" data-action="template">下载接入模板</button><button class="button compact ghost" data-action="metrics-v2-template">指标 v2 模板</button></div></div></div><div class="pipeline-step"><span class="step-num">03</span><div><h3>比赛时间 → 视频时间</h3><p>设置至少一条核对过的时间锚点。多锚点使用分段线性映射；不跨出已校准时间范围自动外推。</p><button class="button compact" data-action="sync">设置同步锚点</button></div></div><div class="pipeline-step"><span class="step-num">04</span><div><h3>按镜头标定球场平面</h3><p>画面坐标可直接叠加；移动镜头使用同一组球场锚点的逐时刻关键帧。缺少独立检查点或遮挡的区间会隐藏投影。</p><button class="button compact" data-action="calibrate" ${!state.url||!p?'disabled':''}>固定镜头标定</button><button class="button compact" data-action="dynamic-keyframe" ${!state.url||!p?'disabled':''}>移动镜头关键帧</button><button class="button compact ghost" data-action="dynamic-cal" ${!p?'disabled':''}>镜头区间与检查</button></div></div></div><div class="panel"><div class="panel-head"><h2>回合检查与编辑</h2><button class="text-link" data-action="history">修订历史</button></div><div class="data-table-wrap"><table class="data-table"><tr><th>回合</th><th>起止时间</th><th>球员</th><th>结果</th><th>球场轨迹</th><th>操作</th></tr>${state.project.plays.map(p=>`<tr><td>${h(p.id)}</td><td>${format(p.start,2)}–${format(p.end,2)} s</td><td>${h(p.player||'未提供')}</td><td>${h(p.outcome)}</td><td>${p.tracks?.length||0} 帧</td><td><button class="button compact" data-action="edit-play" data-id="${h(p.id)}">编辑</button></td></tr>`).join('')}</table></div></div></section><section class="content-column"><div class="panel"><div class="panel-head"><h2>官方指标的定义边界</h2><a class="text-link" href="https://www.nba.com/news/inside-the-game-stat-glossary" target="_blank" rel="noopener">NBA 数据词典 ↗</a></div><div class="panel-body"><div class="source-definition"><b>Shot Difficulty / xFG</b>读取提供者的预期命中率与定义版本。它是预测概率，不是投篮结果，也不等于个人实际命中率。</div><div class="source-definition"><b>Gravity / 球员引力</b>保留官方模型输出。近防守者距离、进攻展开面积只作为几何解释，不替代专有引力模型。</div><div class="source-definition"><b>Leverage / 关键度</b>先确认是回合胜率机会差、球员累计得分还是其他口径。数值范围不能证明语义；不兼容读数不统一缩放。</div><p class="form-note">当前合成演练的 Leverage 是“0–1 回合胜率机会差”。正式赛方字典尚未发布，届时按实际语义接入；不能仅改字段名就当作官方 Leverage。</p></div></div><div class="panel"><div class="panel-head"><h2>Agent 连接与执行</h2><button class="text-link" data-action="agent-settings">设置 ↗</button></div><div class="panel-body"><ul class="boundary-list"><li><strong>本地证据引擎</strong>实际执行读数、时序几何、筛选、证据检索与叙事编排；不是语言模型。</li><li><strong>模型 Agent</strong>本机服务可连接 AWS Bedrock 或本地 Ollama。模型调用注册工具并选择已有声明，不能自由编造数值。</li><li><strong>数据发送范围</strong>只有选定的结构化证据与问题；原视频保留本机。网页不会保存云密钥。</li><li><strong>失败可见</strong>未连接、缺少权限、超时或非法声明明确报错，不用演练回答伪装模型成功。</li></ul></div></div><div class="panel"><div class="panel-head"><h2>这次创新解决什么</h2></div><div class="panel-body"><ul class="boundary-list"><li><strong>观众</strong>从某一时刻读懂跑位、空档与出手选择。</li><li><strong>分析员</strong>追溯每条解释的字段、采样和画面锚点。</li><li><strong>内容创作者</strong>从同一证据生成双层解说与战术片单。</li></ul><p class="form-note">借鉴 NBA/AWS、Second Spectrum 和训练科技的证据工作流。科研与训练技术的使用不能单独证明夺冠因果。</p></div></div></section></div>`;}
function render(){
  stopPlayback();frameObservers.forEach(stop=>stop());frameObservers=[];const route=location.hash.match(/^#\/(watch|lab|director|pipeline)/)?.[1]||'watch';state.route=route;if(route!=='director')cancelPreview();
  $('#navigation').innerHTML=[['watch','film','智能观赛'],['lab','court','战术实验室'],['director','stack','故事导演'],['pipeline','data','素材与校准']].map(([key,ic,title])=>`<a class="nav-link ${key===route?'active':''}" href="#/${key}" ${key===route?'aria-current="page"':''}>${icon(ic)}${title}</a>`).join('');
  $('#project-switch').innerHTML=`${h(state.project?.name||'比赛项目')} <span>⌄</span>`;
  $('#main').innerHTML=state.project?{watch,lab,director,pipeline}[route]():emptyWorkspace();
  $('#storage-status').textContent=state.dirty?'未保存草稿 · 请下载备份后重新载入':state.project?`修订 ${state.project.revision} · 浏览器本机保存`:'浏览器本机存储';
  mountMedia();
}
function viewPlay(p,t,project=state.project){return playAt(project,p,t);}
function setTime(t){const p=play();if(!p)return;state.time=Math.min(p.end,Math.max(p.start,Number(t)));const v=$(`video[data-video="${CSS.escape(p.id)}"]`);if(v&&Math.abs(v.currentTime-state.time)>.015)v.currentTime=state.time;updateFrames();}
