async function ask(question){
  if(!question?.trim())return;const q=question.trim().slice(0,1200);toast('正在读取回合证据…');
  if(state.provider==='local'){const answer=queryEvidence(state.project.plays,q);state.answer={...answer,question:q};render();return;}
  const payload=agentPayload(state.project.plays,state.analyses,state.narrations,{question:q,audience:state.audience,provider:state.provider});
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),55000);let response;try{response=await fetch('/api/arena/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});}finally{clearTimeout(timer);}
  const data=await response.json();if(!response.ok)throw new Error(data.error?.message||data.error||'模型执行失败。');state.answer={...data,question:q};render();
}
