async function importVideo(file){
  if(!file||!file.size)throw new Error('没有选择有效视频。');if(file.size>LIMITS.video)throw new Error('视频超过 512 MiB。');
  const url=URL.createObjectURL(file),v=document.createElement('video');v.preload='metadata';v.src=url;
  const metadata=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('读取视频信息超时。')),20000);v.onloadedmetadata=()=>{clearTimeout(timer);if(!Number.isFinite(v.duration)||v.duration<=0||!v.videoWidth)reject(new Error('视频时长或尺寸无效。'));else resolve({duration:v.duration,width:v.videoWidth,height:v.videoHeight});};v.onerror=()=>{clearTimeout(timer);reject(new Error('浏览器无法解码此视频。'));};}).finally(()=>{URL.revokeObjectURL(url);v.removeAttribute('src');v.load();});
  if(state.project.plays.some(p=>p.end>metadata.duration+.05))throw new Error('部分回合超出该视频时长。请先调整回合时间，或绑定对应的比赛视频。');
  const hash=globalThis.crypto?.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join(''):null;
  const expected=state.project.video?.sha256,matched=!!expected&&expected===hash;
  state.pending={videoFile:file,videoMetadata:{name:file.name,size:file.size,type:file.type,sha256:hash,...metadata},videoMatched:matched,videoChanged:!!expected&&expected!==hash};
  showDialog('核对视频与回合数据',`<p class="dialog-description">${h(file.name)} · ${sec(metadata.duration)} · ${metadata.width} × ${metadata.height}</p><p>${matched?'文件指纹与项目记录一致，可保留已绑定的画面坐标。':expected?'文件指纹与历史素材不同。保存后会关闭旧画面轨迹和标注，并清除镜头标定。原版本可从修订历史恢复。':'项目尚未记录视频指纹。需要先核对数据时间与坐标所对应的原片。'}</p>${!expected?'<label class="review-check"><input id="video-binding-reviewed" type="checkbox">我确认这是回合数据与画面坐标对应的原始视频。</label>':''}<p class="form-note">文件字节保存在当前浏览器。项目备份不含视频，请另行保留原片。</p>`,`<button class="button ghost" data-action="close">取消</button><button class="button primary" data-action="commit-video">保存绑定</button>`);
}
