  const p=play();if(!p||!state.url)return;stopPlayback();state.decision?.frameController?.abort();
  const validShot=Number.isFinite(p.shotTime)&&p.shotTime>p.start&&p.shotTime<=p.end,validResult=p.resultTime==null||(Number.isFinite(p.resultTime)&&p.resultTime>=p.shotTime&&p.resultTime<=p.end);
